import json

session_file = r'C:/Users/Admin/.claude/projects/D--My-Drive-Blue-AI/ee451502-00d9-4bce-8419-eed58abd47d6.jsonl'
tool_counts = {}
hook_errors = 0
agent_spawns = 0
user_messages = []

with open(session_file, 'r', encoding='utf-8') as f:
    for line in f:
        try:
            data = json.loads(line)
            # check type
            if data.get('type') == 'user':
                msg = data.get('message', {})
                content = msg.get('content')
                if isinstance(content, str):
                    user_messages.append((data.get('timestamp'), content[:100]))
                elif isinstance(content, list):
                    for item in content:
                        if isinstance(item, dict) and item.get('is_error'):
                            text = str(item.get('content', ''))
                            if 'hook' in text.lower() or 'gate' in text.lower():
                                hook_errors += 1
            if data.get('type') == 'assistant':
                msg = data.get('message', {})
                content = msg.get('content')
                if isinstance(content, list):
                    for item in content:
                        if item.get('type') == 'tool_use':
                            name = item.get('name')
                            tool_counts[name] = tool_counts.get(name, 0) + 1
        except Exception as e:
            pass

print('User message count:', len(user_messages))
print('Hook errors:', hook_errors)
print('Tool counts:', tool_counts)
print('Last 5 user messages:')
for ts, m in user_messages[-5:]:
    print(ts, m)
"

