import json

session_file = r'C:/Users/Admin/.claude/projects/D--My-Drive-Blue-AI/001510c0-af4c-4ebb-ac15-003480716d4b.jsonl'
tool_counts = {}
user_messages = []
hook_errors = []

with open(session_file, 'r', encoding='utf-8') as f:
    for line in f:
        try:
            d = json.loads(line)
            if d.get('type') == 'user':
                c = d.get('message', {}).get('content')
                if isinstance(c, str):
                    user_messages.append((d.get('timestamp'), c[:120]))
                elif isinstance(c, list):
                    for it in c:
                        if isinstance(it, dict) and it.get('is_error'):
                            hook_errors.append(str(it.get('content'))[:150])
            elif d.get('type') == 'assistant':
                c = d.get('message', {}).get('content')
                if isinstance(c, list):
                    for it in c:
                        if it.get('type') == 'tool_use':
                            name = it.get('name')
                            tool_counts[name] = tool_counts.get(name, 0) + 1
        except:
            pass

print('User messages:', len(user_messages))
print('Hook errors:', len(hook_errors))
print('Tool counts:', tool_counts)
print('User message samples:')
for ts, m in user_messages[:10]:
    print(' ', ts, m.encode('ascii', 'replace').decode('ascii'))
"

